using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
namespace OpenAntiLag {
 public enum OptimizationStage {Ready,Enabled,WaitingForGame,Applying,Restoring,NeedsAction,ErrorRestored,ErrorIncomplete}
 public sealed class BackendProfileState {public string UserPhase,MachinePhase,OwnedPlan;public ProfileOptions Options;public bool Active,Reboot;}
 public sealed class OptimizationStatusModel {
  public OptimizationStage Stage;public string Message,ProfileName="Стандартный";public bool HasProfile,Busy,Faceit;public string[] Applied=new string[0];
  public string Title {get{switch(Stage){case OptimizationStage.Enabled:return "Оптимизация включена";case OptimizationStage.WaitingForGame:return "Ожидание запуска игры";case OptimizationStage.Applying:return "Применение настроек";case OptimizationStage.Restoring:return "Восстановление настроек";case OptimizationStage.NeedsAction:return "Требуется ваше действие";case OptimizationStage.ErrorRestored:return "Ошибка — изменения восстановлены";case OptimizationStage.ErrorIncomplete:return "Восстановление не завершено";default:return "Готов к оптимизации";}}}
 }
 public interface IOptimizationBackend {BackendProfileState Read();void Enable(ProfileOptions options,string[] machine);void Restore();void RestoreBasic();}
 public sealed class ExistingOptimizationBackend:IOptimizationBackend {
  readonly Engine engine;readonly ISystemClient system;readonly ProfileController controller;
  public ExistingOptimizationBackend(Engine engine,ISystemClient system){this.engine=engine;this.system=system;controller=new ProfileController(engine,system);}
  public BackendProfileState Read(){var m=system.State;return new BackendProfileState {UserPhase=engine.State.Phase,MachinePhase=m.Phase,OwnedPlan=engine.State.OwnedPlan,Options=engine.State.Options,Active=engine.IsActive,Reboot=system.RebootPending};}
  public void Enable(ProfileOptions options,string[] machine){controller.Enable(options,machine);}public void Restore(){controller.Disable();}public void RestoreBasic(){engine.Disable();}
 }
 public sealed class PlayerOperation {public DateTime Utc=DateTime.UtcNow;public string Name,Result;public bool Success;public string GameId;}
 public sealed class RecoveryModule {public string Name;public Func<bool> Pending;public Func<string> Restore;}
 public sealed class OptimizationOrchestrator {
  readonly IOptimizationBackend backend;readonly Func<Task<bool>> acquire;readonly Action release;readonly List<PlayerOperation> operations=new List<PlayerOperation>();
  public OptimizationStatusModel Status {get;private set;}public event Action Changed;
  public OptimizationOrchestrator(IOptimizationBackend backend,Func<Task<bool>> acquire,Action release){this.backend=backend;this.acquire=acquire;this.release=release;Status=new OptimizationStatusModel {Stage=OptimizationStage.Ready,Message="Выберите игру и профиль. Изменения выполняются после подтверждения."};}
  public static ProfileOptions Options(PlayerProfile profile){if(profile==PlayerProfile.Custom)throw new ArgumentException("Для пользовательского профиля нужен явный выбор");return new ProfileOptions {GameMode=true,DisableCapture=profile==PlayerProfile.Competitive};}
  public static string ProfileName(PlayerProfile profile){return profile==PlayerProfile.Standard?"Стандартный":profile==PlayerProfile.Competitive?"Соревновательный":"Пользовательский";}
  public static string Summary(ProfileOptions o,string[] machine){var list=new List<string>{"Создать отдельную копию текущего плана питания с сохранением исходного."};if(o.GameMode)list.Add("Включить игровой режим Windows.");if(o.DisableCapture)list.Add("Отключить запись Xbox, включая ручные клипы.");if(o.DisableMouseAcceleration)list.Add("Отключить ускорение курсора мыши.");if(o.CpuReady)list.Add("Питание CPU от сети: минимум 100%, без парковки. Возможен нагрев.");if(o.PcieReady)list.Add("Отключить энергосбережение PCIe от сети.");if(o.Timer)list.Add("Запросить таймер 1 мс на время работы профиля.");if(machine.Length>0)list.Add("Дополнительные системные параметры: "+String.Join(", ",machine)+". Нужны UAC и перезагрузка.");return String.Join("\n",list)+"\n\nНастройки видеокарты, интернет-ограничения и шейдеры управляются отдельно. Прирост FPS/снижение задержки не гарантируются.";}
  void Emit(){var h=Changed;if(h!=null)h();}
  void Record(string name,string result,bool success,string game=null){lock(operations){operations.Add(new PlayerOperation {Name=name,Result=result,Success=success,GameId=game});if(operations.Count>200)operations.RemoveAt(0);}Emit();}
  public void ReportExternal(string name,string result,bool success){Record(name,result,success);}
  public PlayerOperation[] Operations(){lock(operations)return operations.ToArray();}
  public BackendProfileState Read(){return backend.Read();}
  public async Task Refresh(){if(Status.Busy)return;try{var s=await Task.Run(()=>backend.Read());if(Status.Busy)return;Status.HasProfile=s.UserPhase!="Disabled"||s.MachinePhase!="Disabled";if(Status.HasProfile&&s.Options!=null){var o=s.Options;Status.ProfileName=s.MachinePhase=="Disabled"&&o.GameMode&&!o.DisableMouseAcceleration&&!o.CpuReady&&!o.PcieReady&&!o.Timer?(o.DisableCapture?"Соревновательный":"Стандартный"):"Пользовательский / существующий";}if(s.UserPhase=="Restoring"||s.UserPhase=="Applying"||s.MachinePhase=="Restoring"||s.MachinePhase=="Applying"){Status.Stage=OptimizationStage.NeedsAction;Status.Message="Предыдущая операция не завершена. Откройте восстановление настроек.";}else if(s.Reboot){Status.Stage=OptimizationStage.NeedsAction;Status.Message="Системные параметры изменены. Сохраните работу и перезагрузите Windows.";}else if(Status.HasProfile){Status.Stage=s.Active?OptimizationStage.Enabled:OptimizationStage.NeedsAction;Status.Message=s.Active?"Профиль Windows применён. Другие модули управляются отдельно.":"Есть сохранённый профиль. Восстановите его перед новым применением.";}else if(Status.Stage!=OptimizationStage.ErrorRestored){Status.Stage=OptimizationStage.Ready;Status.Message="Можно включить выбранный профиль. Перед применением появится список изменений.";}}catch(Exception e){Status.Stage=OptimizationStage.NeedsAction;Status.Message=e.Message;}Emit();}
  public async Task<bool> Enable(PlayerProfile profile,ProfileOptions options,string[] machine,string gameId=null){if(Status.Busy)return false;if(!await acquire()){Status.Message="Дождитесь завершения текущей операции.";Emit();return false;}bool success=false;Status.Busy=true;Status.Stage=OptimizationStage.Applying;Status.ProfileName=ProfileName(profile);Emit();try{Exception failure=null;try{await Task.Run(()=>backend.Enable(options,machine));var state=await Task.Run(()=>backend.Read());if(!state.Active||state.UserPhase!="Enabled")throw new IOException("Windows не подтвердила активный профиль. Проверьте восстановление.");Status.HasProfile=true;Status.Applied=Summary(options,machine).Split('\n').TakeWhile(s=>s.Length>0).ToArray();Status.Stage=state.Reboot?OptimizationStage.NeedsAction:OptimizationStage.Enabled;Status.Message=state.Reboot?"Настройки записаны. Требуется перезагрузка.":"Выбранные настройки применены и проверены.";Record("Профиль Windows",Status.Message,true,gameId);success=true;}catch(Exception error){failure=error;}if(failure!=null)await SetFailure(failure,"Применение профиля",gameId);}finally{Status.Busy=false;release();Emit();}return success;}
  async Task SetFailure(Exception error,string action,string gameId=null){try{var state=await Task.Run(()=>backend.Read());Status.HasProfile=state.UserPhase!="Disabled"||state.MachinePhase!="Disabled";Status.Stage=Status.HasProfile?OptimizationStage.ErrorIncomplete:OptimizationStage.ErrorRestored;Status.Message=(Status.HasProfile?"Нужно повторить восстановление. ":"Настройки не применены или восстановлены. ")+error.Message;}catch{Status.Stage=OptimizationStage.ErrorIncomplete;Status.Message="Не удалось проверить состояние. "+error.Message;}Record(action,Status.Message,false,gameId);}
  public async Task Restore(bool basic=false){if(Status.Busy)return;if(!await acquire()){Status.Message="Дождитесь завершения текущей операции.";Emit();return;}Status.Busy=true;Status.Stage=OptimizationStage.Restoring;Emit();try{Exception failure=null;try{await Task.Run(()=>{if(basic)backend.RestoreBasic();else backend.Restore();});var s=await Task.Run(()=>backend.Read());if(s.UserPhase!="Disabled"||(!basic&&s.MachinePhase!="Disabled"))throw new IOException("Журнал ещё содержит незавершённые изменения");Status.HasProfile=s.MachinePhase!="Disabled";Status.Applied=new string[0];Status.Stage=s.Reboot||Status.HasProfile?OptimizationStage.NeedsAction:OptimizationStage.Ready;Status.Message=s.Reboot?"Записи восстановлены. Для вступления изменений в силу перезагрузите Windows.":basic&&Status.HasProfile?"Основные параметры восстановлены. Системные изменения восстановите отдельно.":"Параметры профиля Windows восстановлены.";Record("Восстановление Windows",Status.Message,true);}catch(Exception error){failure=error;}if(failure!=null)await SetFailure(failure,"Восстановление Windows");}finally{Status.Busy=false;release();Emit();}}
  public async Task<bool> Module(string name,Func<string> action,Func<bool> verify){if(Status.Busy)return false;if(!await acquire()){Status.Message="Дождитесь завершения текущей операции.";Emit();return false;}Status.Busy=true;Emit();try{string result=await Task.Run(action);if(!await Task.Run(verify))throw new IOException("Состояние модуля не подтвердило завершение");Record(name,result,true);Status.Message=result;return true;}catch(Exception error){Record(name,error.Message,false);Status.Message=name+": "+error.Message;return false;}finally{Status.Busy=false;release();Emit();}}
  public async Task RestoreAll(IEnumerable<RecoveryModule> modules){if(Status.Busy||!await acquire())return;bool complete=true;Status.Busy=true;Status.Stage=OptimizationStage.Restoring;Emit();try{foreach(var module in modules){try{if(!await Task.Run(module.Pending))continue;string result=await Task.Run(module.Restore);if(await Task.Run(module.Pending))throw new IOException("Журнал не подтвердил завершение");Record(module.Name,result,true);}catch(OperationCanceledException){complete=false;Record(module.Name,"Отменено пользователем. Остальные операции не запускались.",false);break;}catch(Exception error){complete=false;Record(module.Name,error.Message,false);}}}finally{Status.Busy=false;release();}await Refresh();Status.Message=complete?"Журналы выбранных модулей подтвердили завершение восстановления. Внешние изменения могли быть сохранены; перезагрузите ПК, если это требуется.":"Не все модули восстановлены. Посмотрите результаты и повторите нужную операцию.";Emit();}
 }
}
